-- Starter schema for Gadgets BD. Review RLS and run in Supabase SQL editor.
create extension if not exists pgcrypto;
create table if not exists public.categories(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,created_at timestamptz not null default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,description text not null default '',brand text not null default '',category_id uuid references public.categories(id) on delete set null,price numeric(12,2) not null check(price>=0),compare_at_price numeric(12,2),stock integer not null default 0 check(stock>=0),image_url text not null default '',is_active boolean not null default true,is_featured boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',phone text not null default '',address text not null default '',created_at timestamptz not null default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete set null,customer_name text not null,phone text not null,delivery_address text not null,subtotal numeric(12,2) not null check(subtotal>=0),delivery_fee numeric(12,2) not null default 0,total numeric(12,2) not null check(total>=0),payment_method text not null default 'cod' check(payment_method in('cod','gateway')),payment_status text not null default 'pending' check(payment_status in('pending','paid','failed','refunded')),status text not null default 'pending' check(status in('pending','confirmed','processing','shipped','delivered','cancelled')),created_at timestamptz not null default now());
create table if not exists public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id) on delete set null,product_name text not null,unit_price numeric(12,2) not null,quantity integer not null check(quantity>0),line_total numeric(12,2) not null);
create table if not exists public.wishlists(user_id uuid not null references auth.users(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,product_id));
create table if not exists public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade,role text not null check(role in('owner','admin','staff')));
alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.profiles enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.wishlists enable row level security; alter table public.admin_users enable row level security;
create policy "Read categories" on public.categories for select using(true);
create policy "Read active products" on public.products for select using(is_active=true);
create policy "Read own profile" on public.profiles for select to authenticated using(auth.uid()=id);
create policy "Insert own profile" on public.profiles for insert to authenticated with check(auth.uid()=id);
create policy "Update own profile" on public.profiles for update to authenticated using(auth.uid()=id) with check(auth.uid()=id);
create policy "Read own orders" on public.orders for select to authenticated using(auth.uid()=user_id);
create policy "Read own order items" on public.order_items for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid()));
create policy "Manage own wishlist" on public.wishlists for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
-- Create orders/admin mutations through a trusted Edge Function. Never let a user self-assign admin role.
